-- =============================================================================
-- «Қайда?» · Миграция 9: стартовая база упаковок по штрихкоду (MVP)
-- Сгенерировано workflow ai-train.yml: db/packages/collect_packages.py
-- Источники: Open Food Facts / Open Products Facts (ODbL) и синтетика (бренды выдуманы).
-- =============================================================================
-- СГЕНЕРИРОВАНО db/packages/collect_packages.py — база упаковок по штрихкоду.
on conflict (gtin) do update set name = coalesce(excluded.name, packages.name), brand = coalesce(excluded.brand, packages.brand),
  quantity = coalesce(excluded.quantity, packages.quantity), material = excluded.material, shape = excluded.shape,
  ai_class = excluded.ai_class, raw = excluded.raw
  where not packages.verified;
